<script lang="ts">import Icon from '$lib/components/Icon.svelte';import {mailCommand,mailId} from '$lib/mail/store';import {address,type Mailbox,type Message} from '$lib/mail/model.js';export let mailbox:Mailbox;export let original:Message|undefined=undefined;export let mode:'new'|'reply'|'forward'|'draft'='new';export let onClose:()=>void;export let onSaved:(intent:'draft'|'send')=>void;let to=mode==='draft'?original?.to||'':mode==='reply'?(original?.folder==='Sent'?original?.to:original?.address)||'':'',subject=mode==='draft'?original?.subject||'':mode==='reply'?'Re: '+(original?.subject||'').replace(/^Re: /i,''):mode==='forward'?'Fwd: '+(original?.subject||''):'',body=mode==='draft'?original?.body||'':original&&mode!=='new'?'\n\n--- '+(mode==='reply'?'Original':'Forwarded')+' message ---\nFrom: '+original.from+' <'+original.address+'>\nSubject: '+original.subject+'\n\n'+original.body:'',error='';function submit(intent:'draft'|'send'){try{mailCommand({type:'compose',mailbox:mailbox.id,id:mailId(),draft:mode==='draft'?original?.id:undefined,to,subject,body,intent});onSaved(intent);}catch(e){error=e instanceof Error?e.message:'Could not save message.';}}</script>
<div class="native-compose" role="region" aria-label="Compose message"><form class="native-compose-form card stack" on:submit|preventDefault={()=>submit('send')}><div class="row between wrap"><div><h3>{mode==='draft'?'Edit draft':'New message'}</h3><p class="subtitle">{address(mailbox)}</p></div><button class="btn secondary small" type="button" on:click={onClose}>Close</button></div><label class="field">To<input type="email" maxlength="320" bind:value={to} placeholder="name@example.net" required/></label><label class="field">Subject<input bind:value={subject} maxlength="300" placeholder="Subject"/></label><label class="field grow">Message<textarea bind:value={body} rows="10" maxlength="50000" placeholder="Write your message…"></textarea></label>{#if error}<p class="error" role="alert">{error}</p>{/if}<small>Local simulation. Sending adds a copy to Sent; no message leaves this browser.</small><div class="native-actions"><button class="btn secondary" type="button" on:click={()=>submit('draft')}>Save draft</button><button class="btn primary" type="submit"><Icon name="Email"/>Send</button></div></form></div>
